// Politikregistret: över hundra områden som spelaren bygger själv. Varje område har
//   type   'slider' (min/max/step/def/unit) eller 'choice' (options med v = -1…1)
//   def    gällande lag i Sverige vid spelets start (= nollpunkten på kompassen)
//   axes   hur området bidrar till de tolv väljaraxlarna (tecken = riktning när värdet ökar)
//   comp   bidrag till den niodimensionella kompassen (ek, auk, glob, prog, cent, mil, sek, mark, miljo)
//   lag    månader tills reformen får full effekt (myndigheternas kapacitet)
//   cost   extra kostnad (+) eller intäkt (−) i mdkr/år jämfört med gällande lag
//   fx     effekter på simuleringen, skrivs in i ett "fx"-objekt som sweden.js läser
//   konst  grundlag: kräver två riksdagsbeslut med ett val emellan
// Värdena är spelets modell av Sverige – rimliga storleksordningar, inte officiell statistik.
const S = (id, domain, name, o) => ({ id, domain, name, type: 'slider', ...o });
const C = (id, domain, name, o) => ({ id, domain, name, type: 'choice', ...o });
const n = (p, v) => (p.type === 'choice' ? (p.options.find((x) => x.id === v)?.v ?? 0) : v <= p.def ? (p.def - p.min ? -(p.def - v) / (p.def - p.min) : 0) : (p.max - p.def ? (v - p.def) / (p.max - p.def) : 0)); // -1…1

export const DOMAINS = {
  migration: 'Migration & integration', skatter: 'Skatter', ekonomi: 'Ekonomi & ägande', arbete: 'Arbetsmarknad', valfard: 'Vård & omsorg', socialt: 'Socialförsäkringar', utbildning: 'Skola & forskning',
  ratt: 'Brott & straff', frihet: 'Fri- & rättigheter', demokrati: 'Statsskick & demokrati', forsvar: 'Försvar', utrikes: 'Utrikes & EU', energi: 'Energi & klimat', samhalle: 'Infrastruktur, bostad & samhälle',
};
export const COMPASS = [
  { id: 'ek', name: 'Ekonomisk', left: 'vänster', right: 'höger' }, { id: 'auk', name: 'Makt', left: 'libertär', right: 'auktoritär' }, { id: 'glob', name: 'Omvärld', left: 'globalistisk', right: 'nationalistisk' },
  { id: 'prog', name: 'Kultur', left: 'progressiv', right: 'traditionalistisk' }, { id: 'cent', name: 'Styrning', left: 'decentraliserad', right: 'centraliserad' }, { id: 'mil', name: 'Säkerhet', left: 'pacifistisk', right: 'militaristisk' },
  { id: 'sek', name: 'Religion', left: 'sekulär', right: 'religiös' }, { id: 'mark', name: 'Välfärd', left: 'statsorienterad', right: 'marknadsorienterad' }, { id: 'miljo', name: 'Miljö', left: 'miljöorienterad', right: 'industriorienterad' },
];

